class YellowDoorsCount(PresetRange):
    """
    Power Bomb Doors.

    This setting determines the types of non-gray doors that exist in the game:
    - Blue: All doors are blue, except for gray doors.
    - Ammo: Red, green, and yellow doors are randomly mixed in.
    - Beam: Beam doors are randomly mixed in, replacing some of the ammo doors.
    Gray doors are unaffected by this setting and always exist in the same set of rooms: boss/miniboss rooms and
    the four Pirates rooms (Pit Room, Baby Kraid Room, Plasma Room, and Metal Pirates Room).
    For ammo and beam doors, both sides of the door will have the same color and share a lock, so that unlocking
    one side of the door also unlocks the other.
    Ammo and beam doors will not be placed on or immediately connect to any special tile such as a save, map,
    refill, objective "X", or a gray door.
    Click on the gear icon to customize the number of ammo and beam doors that can appear. This sets the maximum
    number of doors, and the randomizer will attempt to place that many. In certain cases, fewer doors than the
    maximum can be placed.

    Range: 0 to 100. 'preset' keeps the value from the selected preset.
    """
    display_name = "Power Bomb Doors"
    path = "doors_settings.yellow_doors_count"
    range_start = 0
    range_end = 100


