class AreaAssignment(PresetChoice):
    """
    Area assignment.

    Each map is partitioned into six connected regions, which are assigned to in-game areas in different ways
    depending on this setting:
    - Standard: Landing Site is always in Crateria. Mother Brain Room is always in Tourian. The other areas are
        assigned based on their size, from largest to smallest: Norfair, Brinstar, Maridia, Wrecked Ship.
    - Size: The areas are assigned based on their size (in number of map tiles), from largest to smallest:
        Norfair, Brinstar, Maridia, Crateria, Tourian, Wrecked Ship.
    - Depth: The areas are assigned based on their highest map tile, from highest to lowest: Crateria, Wrecked
        Ship, Tourian, Brinstar, Maridia, Norfair.
    - Random: The areas are assigned randomly.
    Additional options are available by clicking the gear button on the right.

    A preset for this group of settings. 'preset' keeps the group from the selected category preset; the
    individual settings below can still be changed.
    """
    display_name = "Area assignment"
    path = "other_settings.area_assignment.preset"
    option_standard = 1
    option_size = 2
    option_depth = 3
    option_randomized = 4
    json_values = {1: 'Standard', 2: 'Size', 3: 'Depth', 4: 'Random'}


