class CustomStartLocation(FreeText):
    """
    Custom start location.

    The start location used when start_location is 'custom', by name (one of the Map Rando start locations, e.g.
    'Landing Site' or 'Bomb Torizo Room'; see the start location list on maprando.com). Ignored otherwise.
    Option<usize>; null unless mode is 'Custom'. Set from the selected <option data-room-id> in the
    'customStartLocation' select. The select's first option is 'unspecified' ('Select a specific location to start
    at'); the remaining options are grouped into <optgroup> by area (game_data.area_order, using each room's full
    area name) and sorted by (room name, location name) within each area; option text is the start location name
    """
    display_name = "Custom start location"
    default = ""


class SaveAnimals(PresetChoice):
    """
    Save the animals.

    This setting affects whether saving the animals (Etecoons and Dachora) will be possible and/or required in the
    escape:
    - No: Saving the animals might not be possible, as the escape timer does not account for it.
    - Yes: Extra escape time is given, and the player is required to save the animals.
    - Optional: Extra escape time is given, making it possible but not required to save the animals.
    - Random: "No" or "Yes" is selected with 50% probability each. The player finds out during the escape.

    'preset' keeps the value from the selected preset.
    """
    display_name = "Save the animals"
    path = "save_animals"
    option_no = 1
    option_yes = 2
    option_optional = 3
    option_randomized = 4
    json_values = {1: 'No', 2: 'Yes', 3: 'Optional', 4: 'Random'}


class WallJump(PresetChoice):
    """
    Wall jump.

    This affects how the wall jump ability works in the game.
    - Vanilla: Wall jumping behaves like in the vanilla game.
    - Collectible: A special new "WallJump" item is added to the game (replacing one "Missile" pack), and wall
        jumping is only possible after collecting this item.
    This setting is taken into account in the logic. The "Collectible" option may significantly increase the
    difficulty of the game, by requiring the player to know how to perform many tricks to avoid wall jumping
    (using frozen enemies, Speed Booster, Bombs, etc.), depending on the Skill Assumption settings.
    Regardless of this setting, it is always possible to get a wall-jump check (the pose that Samus makes when
    moving away from a nearby wall), even if pressing jump during the check will not trigger a wall jump.
    When the "Collectible" walljump option is enabled, hazard markings are shown on doors leading to three
    additional locations:
    - Door leading left to the top of Ridley's Room.
    - Door leading left to the drop-off in West Ocean (e.g. from Gravity Suit Room in vanilla).
    - Door leading down to Crocomire's Room.

    'preset' keeps the value from the selected preset.
    """
    display_name = "Wall jump"
    path = "other_settings.wall_jump"
    option_vanilla = 1
    option_collectible = 2
    json_values = {1: 'Vanilla', 2: 'Collectible'}


class SpeedBooster(PresetChoice):
    """
    Speed Booster.

    This affects the Speed Booster item.
    - Vanilla: Speed Booster is a single collectible item and functions identically to the vanilla game.
    - Split: Speed Booster is replaced with two new collectible items, "Spark Booster" and "Blue Booster".
    - Blue Booster allows Samus to run, gain blue, and jump at high speeds, but not to shinespark.
    - Spark Booster allows Samus to shinespark, but not to jump with blue or high speed.
    - Either item allows Samus to run through enemies, Speed blocks, and bomb blocks.
    This setting is taken into account in the logic.

    'preset' keeps the value from the selected preset.
    """
    display_name = "Speed Booster"
    path = "other_settings.speed_booster"
    option_vanilla = 1
    option_split = 2
    json_values = {1: 'Vanilla', 2: 'Split'}


