class RoomTheming(Choice):
    """
    Room theming.

    This setting controls the graphical appearance of rooms.
    - Vanilla: Rooms appear as they do in the vanilla game.
    - Area Palettes: Rooms colors are adjusted to follow a consistent theme for each area. This provides some
        amount of variety and cohesiveness in room appearance, while still allowing easy recognizability of rooms.
    - Area Tiling: Rooms graphics are redrawn to follow a consistent theme for each area. This provides the
        highest level of variety and cohesiveness in room appearance.
    Other variations of these options are available under "Other customization options".
    """
    display_name = "Room theming"
    field = "room_theming"
    option_vanilla = 0
    option_palettes = 1
    option_tiling = 2
    default = 2
    json_values = {0: 'vanilla', 1: 'palettes', 2: 'tiling'}


class RoomPalettes(Choice):
    """
    Room palettes.

    This setting controls the palettes for rooms (affecting foregrounds and backgrounds):
    - Vanilla: Rooms use the palette from the original game.
    - Area-themed: Each room uses a palette based on its area in the randomized map.
    - Area-shuffled: Each area is randomly assigned one of the six area palette themes, with every palette used
        exactly once.
    - Scrambled: Each room uses a random selection of one of six possible palettes.
    - If an individual area is selected (e.g. Crateria), then all rooms use a palette based on that area.

    'room_theming' (the default) uses the value given by the room_theming option.
    """
    display_name = "Room palettes"
    field = "room_palettes"
    option_room_theming = 0
    option_vanilla = 1
    option_area_themed = 2
    option_area_shuffled = 3
    option_scrambled = 4
    option_crateria = 5
    option_brinstar = 6
    option_norfair = 7
    option_wrecked_ship = 8
    option_maridia = 9
    option_tourian = 10
    default = 0
    json_values = {0: None, 1: 'vanilla', 2: 'area-themed', 3: 'area-shuffled', 4: 'scrambled', 5: 'crateria', 6: 'brinstar', 7: 'norfair', 8: 'wrecked-ship', 9: 'maridia', 10: 'tourian'}


class TileTheme(Choice):
    """
    Tile theme.

    This setting controls how the rooms in the game will be drawn. This affects only the graphical appearance of
    the rooms.
    - If Vanilla is selected, then rooms are tiled as they are in the vanilla game.
    - If Area-themed is selected, then rooms are tiled according to their area on the map.
    - If Area-shuffled is selected, then the tile themes are randomly shuffled across the six areas. Rooms within
        an area retain consistent subarea theming.
    - If Scrambled is selected, then each room is tiled using a random theme.
    - If an individual theme is selected (e.g. Outer Crateria), then all the rooms are tiled using that theme.
    - If Practice Outlines is selected, then rooms are tiled using green outlines to mark the room collision;
        special blocks are shown in their true form; and a background grid helps with measuring positions and
        distances.
    - If Invisible is selected, then rooms are tiled using blank, transparent foreground, making the game
        difficult to navigate. Doors will still be visible, as will vanilla backgrounds and sprites.
    With Area-themed, Area-shuffled, or Scrambled modes, rooms that directly connect to Tourian will use the
    Statues Hallway theme. For Area-themed and Area-shuffled modes, any single-doored room next to such a room
    will also use the Statues Hallway theme.

    'room_theming' (the default) uses the value given by the room_theming option.
    """
    display_name = "Tile theme"
    field = "tile_theme"
    option_room_theming = 0
    option_none = 1
    option_area_themed = 2
    option_area_shuffled = 3
    option_scrambled = 4
    option_outer_crateria = 5
    option_inner_crateria = 6
    option_blue_brinstar = 7
    option_green_brinstar = 8
    option_pink_brinstar = 9
    option_red_brinstar = 10
    option_warehouse_brinstar = 11
    option_upper_norfair = 12
    option_lower_norfair = 13
    option_wrecked_ship = 14
    option_west_maridia = 15
    option_yellow_maridia = 16
    option_bedrock = 17
    option_mecha_tourian = 18
    option_metroid_habitat = 19
    option_statues_hallway = 20
    option_outline = 21
    option_invisible = 22
    default = 0
